import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;800`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type FloatingScheduleProps = Record<string, any>;

const SHUFFLE_PATHS = [
  [[0, 1], [2, 0], [4, 2], [6, 1]], 
  [[1, 2], [3, 1], [5, 3], [0, 2]], 
  [[3, 0], [1, 2], [6, 0], [4, 1]], 
  [[5, 3], [4, 2], [1, 1], [2, 3]], 
  [[2, 1], [6, 3], [0, 0], [5, 2]],
  [[4, 3], [0, 1], [3, 2], [1, 0]],
  [[6, 0], [5, 1], [2, 3], [3, 1]],
];

const DAYS = ["MON", "TUE", "WED", "THU", "FRI", "SAT", "SUN"];
const COLUMNS = 7;
const ROWS = 4;

const FloatingSchedule: React.FC<FloatingScheduleProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = true,
  durationInSeconds = 4,
  gridColor = "rgba(255, 255, 255, 0.4)",
  gridThickness = 2,
  techNames = ["Mike", "Dave", "Carlos", "Sarah"],
  shiftColors = ["#ff9f43", "#ffffff"],
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout calculations
  const gridWidth = width * 0.8;
  const gridHeight = height * 0.6;
  const cellW = gridWidth / COLUMNS;
  const cellH = gridHeight / ROWS;
  const offsetX = (width - gridWidth) / 2;
  const offsetY = (height - gridHeight) / 2 + height * 0.05;

  // Timing calculations
  const totalFrames = durationInSeconds * fps;
  const entryDuration = Math.floor(totalFrames * 0.15);
  const shuffleTime = totalFrames - entryDuration;
  const interval = Math.floor(shuffleTime / 3);

  const t1Start = entryDuration;
  const t2Start = entryDuration + interval;
  const t3Start = entryDuration + interval * 2;

  // Global entry animation
  const entrySpring = spring({
    frame,
    fps,
    config: { damping: 14, mass: 0.8 },
    durationInFrames: entryDuration,
  });

  const entryTranslateX = interpolate(entrySpring, [0, 1], [width, 0]);
  const entryOpacity = interpolate(entrySpring, [0, 1], [0, 1]);

  const verticalLines = useMemo(() => {
    return Array.from({ length: COLUMNS + 1 }).map((_, i) => (
      <div
        key={`v-${i}`}
        style={{
          position: "absolute",
          left: i * cellW,
          top: 0,
          width: gridThickness,
          height: gridHeight,
          backgroundColor: gridColor,
          transition: "none",
        }}
      />
    ));
  }, [COLUMNS, cellW, gridHeight, gridColor, gridThickness]);

  const horizontalLines = useMemo(() => {
    return Array.from({ length: ROWS + 1 }).map((_, i) => (
      <div
        key={`h-${i}`}
        style={{
          position: "absolute",
          left: 0,
          top: i * cellH,
          width: gridWidth,
          height: gridThickness,
          backgroundColor: gridColor,
          transition: "none",
        }}
      />
    ));
  }, [ROWS, cellH, gridWidth, gridColor, gridThickness]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter", overflow: "hidden" }}>
      <div
        style={{
          position: "absolute",
          width: gridWidth,
          height: gridHeight,
          left: offsetX,
          top: offsetY,
          transform: `translateX(${entryTranslateX}px)`,
          opacity: entryOpacity,
          transition: "none",
        }}
      >
        {/* Render Grid Lines */}
        {verticalLines}
        {horizontalLines}

        {/* Render Day Labels */}
        {DAYS.map((day, i) => (
          <div
            key={day}
            style={{
              position: "absolute",
              left: i * cellW,
              top: -45,
              width: cellW,
              textAlign: "center",
              color: gridColor.replace(/[\d.]+\)$/g, '0.8)'), // increase opacity for text
              fontSize: 18,
              fontWeight: 700,
              letterSpacing: "0.1em",
              transition: "none",
            }}
          >
            {day}
          </div>
        ))}

        {/* Render Technicians */}
        {techNames.map((name, i) => {
          const path = SHUFFLE_PATHS[i % SHUFFLE_PATHS.length];
          const color = shiftColors[i % shiftColors.length];
          
          const xVals = path.map(p => p[0] * cellW + cellW * 0.15);
          const yVals = path.map(p => p[1] * cellH + cellH * 0.35);

          const t1 = spring({ frame: frame - t1Start, fps, config: { damping: 15, mass: 0.9 } });
          const t2 = spring({ frame: frame - t2Start, fps, config: { damping: 15, mass: 0.9 } });
          const t3 = spring({ frame: frame - t3Start, fps, config: { damping: 15, mass: 0.9 } });

          const currentX = xVals[0]
            + (xVals[1] - xVals[0]) * t1
            + (xVals[2] - xVals[1]) * t2
            + (xVals[3] - xVals[2]) * t3;

          const currentY = yVals[0]
            + (yVals[1] - yVals[0]) * t1
            + (yVals[2] - yVals[1]) * t2
            + (yVals[3] - yVals[2]) * t3;

          // Add a subtle rotation bump during movement
          const bump = Math.sin(t1 * Math.PI) + Math.sin(t2 * Math.PI) + Math.sin(t3 * Math.PI);
          const maxRotation = i % 2 === 0 ? 6 : -6;
          const rotation = interpolate(bump, [0, 1], [0, maxRotation]);

          // Continuous floating effect
          const floatY = Math.sin((frame + i * 20) / 15) * 4;

          return (
            <div
              key={`tech-${i}`}
              style={{
                position: "absolute",
                display: "flex",
                alignItems: "center",
                gap: "12px",
                transform: `translate(${currentX}px, ${currentY + floatY}px) rotate(${rotation}deg)`,
                textShadow: "0px 6px 16px rgba(0,0,0,0.7)",
                transition: "none",
                zIndex: Math.floor(bump * 10) + 10, // Bring to front while moving
              }}
            >
              <div
                style={{
                  width: 14,
                  height: 14,
                  borderRadius: "50%",
                  backgroundColor: color,
                  boxShadow: "0px 4px 8px rgba(0,0,0,0.5)",
                  transition: "none",
                }}
              />
              <span
                style={{
                  color: "#ffffff",
                  fontSize: 32,
                  fontWeight: 800,
                  transition: "none",
                }}
              >
                {name}
              </span>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default FloatingSchedule;